--- a/src/greet.js
+++ b/src/greet.js
@@ -2,13 +2,18 @@

 const DEFAULT = "friend";

+// NFC, so "é" typed as e + combining accent greets the same as the single code point.
+function normalise(name) {
+  return name.normalize("NFC").trim();
+}
+
 function greet(name) {
-  if (!name) return `Hello, ${DEFAULT}!`;
-  return `Hello, ${name.trim()}!`;
+  if (!name || !normalise(name)) return `Hello, ${DEFAULT}!`;
+  return `Hello, ${normalise(name)}!`;
 }

 function shout(name) {
   return greet(name).toUpperCase();
 }

-module.exports = { greet, shout };
+module.exports = { greet, shout, normalise };
